/** Gemini star from the locked reference (blue → purple → red gradient). */
function GeminiStar({ size }: { size: number }): preact.JSX.Element {
  const idRef = useRef<string | null>(null);
  if (idRef.current === null) idRef.current = `muze-gemini-gradient-${++geminiGradientCounter}`;
  return (
    <svg width={size} height={size} viewBox="0 0 24 24" aria-hidden="true">
      <defs>
        <linearGradient id={idRef.current} x1="0" y1="0" x2="1" y2="1">
          <stop offset="0" stop-color="#4285F4" />
          <stop offset=".5" stop-color="#9B72CB" />
          <stop offset="1" stop-color="#D96570" />
        </linearGradient>
      </defs>
      <path fill={`url(#${idRef.current})`} d="M12 2c.8 5.5 3.5 8.2 9 9-5.5.8-8.2 3.5-9 9-.8-5.5-3.5-8.2-9-9 5.5-.8 8.2-3.5 9-9z" />
    </svg>
  );
}

